{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS botanical-luxuriate-wh.MAPLEMONK.platform_net_income_config ( marketplace STRING, payment_mode STRING, gross_per_order FLOAT64, net_factor FLOAT64 ); TRUNCATE TABLE botanical-luxuriate-wh.MAPLEMONK.platform_net_income_config; INSERT INTO botanical-luxuriate-wh.MAPLEMONK.platform_net_income_config VALUES (\'WEBSITE\', \'PREPAID\', NULL, 0.99), (\'WEBSITE\', \'COD\', NULL, 0.60), (\'AMAZON\', \'ALL\', 270, 0.84), (\'FLIPKART\', \'ALL\', 245, 0.70), (\'MEESHO-API\', \'ALL\', 310, 0.758), (\'NYKAA\', \'ALL\', 257.54, 1.00), (\'MYNTRA PPMP\', \'ALL\', 355, NULL), (\'SNAPDEAL\', \'ALL\', 389, NULL), (\'OFFLINE\', \'ALL\', NULL, 1.00), (\'BLINKIT\', \'ALL\', 389, 0.491), (\'JIO MART\', \'ALL\', 389, 0.797), (\'TATA 1MG\', \'ALL\', 480, 0.577), (\'FIRSTCRY\', \'ALL\', 378, 0.620); CREATE OR REPLACE table botanical-luxuriate-wh.MAPLEMONK.daily_pnl_income AS with sales_base AS ( SELECT order_date, marketplace, CASE WHEN UPPER(COALESCE(payment_mode, \'\')) = \'COD\' THEN \'COD\' ELSE \'PREPAID\' END AS payment_mode, COUNT(DISTINCT order_id) AS orders, SUM(selling_price) AS actual_gross FROM botanical-luxuriate-wh.MAPLEMONK.botanical_luxuriate_wh_sales_consolidated WHERE LOWER(order_status) NOT IN (\'cancelled\') GROUP BY 1, 2, 3 ) SELECT s.order_date AS report_date, s.marketplace, CASE WHEN s.marketplace = \'WEBSITE\' AND s.payment_mode = \'COD\' THEN \'WEBSITE - COD (40% Return)\' WHEN s.marketplace = \'WEBSITE\' THEN \'WEBSITE - Prepaid (1% Return)\' ELSE s.marketplace END AS platform_label, s.payment_mode, s.orders, ROUND(CASE WHEN s.marketplace = \'WEBSITE\' THEN s.actual_gross ELSE COALESCE(cfg.gross_per_order, 0) * s.orders END, 2) AS gross_income, ROUND(CASE WHEN s.marketplace = \'WEBSITE\' THEN s.actual_gross * COALESCE(cfg.net_factor, 1) WHEN cfg.net_factor IS NULL THEN NULL ELSE COALESCE(cfg.gross_per_order, 0) * s.orders * cfg.net_factor END, 2) AS net_income FROM sales_base s LEFT JOIN ( SELECT *, ROW_NUMBER() OVER (PARTITION BY marketplace, payment_mode ORDER BY 1) rw FROM botanical-luxuriate-wh.MAPLEMONK.platform_net_income_config ) cfg ON UPPER(s.marketplace) = UPPER(cfg.marketplace) AND (cfg.payment_mode = \'ALL\' OR s.payment_mode = cfg.payment_mode) WHERE cfg.rw = 1 ; CREATE OR REPLACE table botanical-luxuriate-wh.MAPLEMONK.daily_pnl_expenses AS WITH als AS ( SELECT order_date AS expense_date, \'Logistics\' AS expense_category, \'ALS\' AS expense_name, ROUND(COUNT(DISTINCT order_id) * 72.45, 2) AS amount FROM botanical-luxuriate-wh.MAPLEMONK.botanical_luxuriate_wh_sales_consolidated WHERE LOWER(order_status) NOT IN (\'cancelled\') GROUP BY 1 ), ad_spend AS ( SELECT date AS expense_date, \'Ad Spend\' AS expense_category, UPPER(channel) AS expense_name, ROUND(SUM(COALESCE(spend, 0)), 2) AS amount FROM botanical-luxuriate-wh.MAPLEMONK.botanical_luxuriate_wh_MARKETING_CONSOLIDATED GROUP BY 1, 2, 3 ), all_dates AS ( SELECT DISTINCT order_date AS expense_date FROM botanical-luxuriate-wh.MAPLEMONK.botanical_luxuriate_wh_sales_consolidated ), other_costs AS ( SELECT d.expense_date, \'Fixed Cost\' AS expense_category, TRIM(oc.Cost_name) AS expense_name, ROUND( CAST(REPLACE(REPLACE(TRIM(oc.Cost_value), \',\', \'\'), \'\"\', \'\') AS FLOAT64) , 2) AS amount FROM botanical-luxuriate-wh.MAPLEMONK.botlux_gs_Other_Costs oc CROSS JOIN all_dates d ) SELECT expense_date, expense_category, expense_name, amount FROM als UNION ALL SELECT expense_date, expense_category, expense_name, amount FROM ad_spend UNION ALL SELECT expense_date, expense_category, expense_name, amount FROM other_costs;",
                    "transaction": true
                }
            ) }}
